head.script:
scwin.screenId = "jldstf07430";

///////// 1. 변수 및 선언 영역 /////////

scwin.clm_plandoc_submit_dd = undefined;

scwin.bill_submit_schdl_dd = undefined;

scwin.bill_submit_dd = undefined;

scwin.found_dd = undefined;

scwin.acntcls_mmdd1 = undefined;

scwin.exst_strt_dd = undefined;

scwin.exst_end_dd = undefined;

scwin.acntcls_mmdd2 = undefined;

scwin.acntcls_mmdd3 = undefined;

scwin.acntcls_mmdd4 = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "txa_majshrhdContn", attr: "label", fn: function () { return String(dma_comInfo.get("majshrhdContn")); } },
        { childId: "txa_remk", attr: "label", fn: function () { return String(dma_comInfo.get("remk")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_acntclsMmdd1", fn: function(){ return ((dma_comInfo.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd1"); })()) !== ''); } }, { id: "if_secugrpId", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !=='RT'); } }, { id: "if_secugrpId_2", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) ==='FS'); } }, { id: "if_secugrpId_3", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'DR'); } }, { id: "if_exstStrtDd", fn: function(){ return ((dma_comInfo.get("exstStrtDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstStrtDd"); })()) !== ''); } }, { id: "if_exstEndDd", fn: function(){ return ((dma_comInfo.get("exstEndDd") ?? (() => { throw new Error("unresolved:" + "comInfo.exstEndDd"); })()) !== ''); } }, { id: "if_acntclsMmdd1_2", fn: function(){ return ((dma_comInfo.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd1"); })()) !== ''); } }, { id: "if_acntclsMmdd2", fn: function(){ return ((dma_comInfo.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd2"); })()) !== ''); } }, { id: "if_acntclsMmdd3", fn: function(){ return ((dma_comInfo.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd3"); })()) !== ''); } }, { id: "if_acntclsMmdd4", fn: function(){ return ((dma_comInfo.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "comInfo.acntclsMmdd4"); })()) !== ''); } }, { id: "if_secugrpId_4", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) === 'RT'); } }, { id: "if_listTpClssCd_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.listTpClssCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listTpClssCd")) ==='06' ||  ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.listTpClssCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listTpClssCd")) ==='02'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb3", fn: function () { return String(dma_comInfo.get("ventStrtYymm")) + " ~ " + String(dma_comInfo.get("ventEndYymm")); } },
        { childId: "__rb4", fn: function () { return String(dma_comInfo.get("innoBizAhthStrtYymm")) + " ~ " + String(dma_comInfo.get("innoBizAhthEndYymm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldstf07430: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07430.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07430.btn_print_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_leadcomList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_leadcomList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_leadcomList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_leadcomList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.openInfoWin1 === 'function') { await scwin.openInfoWin1(); } else { console.error('[sdd] 행 동작 미정의: scwin.openInfoWin1 (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openInfoWin1'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_leadcomList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
