*/
scwin.openInfoWin1 = async function () {
    /* sdd-asis-lifecycle:begin fn_openInfoWin1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const infoWin = new Object();
    const url = "/jldfil55300_1/jldfil55300_1.xml";
    const style = "dialogWidth:580px;dialogHeight:200px;scroll:no;resize:no";
    Object.assign(infoWin, (await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { type: 'pageFramePopup', modal: true }, infoWin)) || {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openInfoWin2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openInfoWin2 = async function () {
    /* sdd-asis-lifecycle:begin fn_openInfoWin2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const infoWin = new Object();
    const url = "/jldfil55300_2/jldfil55300_2.xml";
    const style = "dialogWidth:580px;dialogHeight:200px;scroll:no;resize:no";
    Object.assign(infoWin, (await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { type: 'pageFramePopup', modal: true }, infoWin)) || {});
    /* sdd-asis-lifecycle:end */
};
